def large_product(nums1, nums2, N):
    # Handle edge cases
    if not nums1 or not nums2 or N <= 0:
        return []

    # Use a max-heap to keep track of the N largest products
    max_heap = []
    for x in nums1:
        for y in nums2:
            product = x * y
            if len(max_heap) < N:
                heapq.heappush(max_heap, product)
            else:
                heapq.heappushpop(max_heap, product)

    # Extract the products from the heap
    largest_products = [-heapq.heappop(max_heap) for _ in range(len(max_heap))]
    # Return the products in descending order
    return largest_products[::-1]

