    if index >= n or k >= n or k <= index:
        return 0

    # Initialize a DP array where dp[i] represents the maximum sum of increasing subsequence
    # up to index i including element at index i
    dp = [0] * n
    dp[index] = a[index]

    # Fill the DP array
    for i in range(index + 1, n):
        if a[i] > a[index]:
