def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    encrypted = ''
    for char in s:
        if char.isalpha():
            shift = (2 * 2) % 26  # Shift down by 2 multiplied to 2 places
            if char.islower():
                new_char = alphabet[(alphabet.index(char) + shift) % 26]
            else:
                new_char = alphabet[(alphabet.index(char.lower()) + shift) % 26].upper()
            encrypted += new_char
        else:
            encrypted += char
    return encrypted

