import heapq

def minPath(grid, k):
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    heap = [(grid[0][0], (0, 0))]

    while heap:
        path = heapq.heappop(heap)
        value, (i, j) = path

        if len(path) == k:
            return [cell[0] for cell in path]

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                heapq.heappush(heap, ((value << (n * n)) + grid[ni][nj], (ni, nj)))

    return []

