def get_median(arr1, arr2, n):
    # If the first array is empty, return the median of the second array
    if n == 0:
        return (arr2[0] + arr2[1]) / 2.0 if n == 1 else (arr2[n//2] + arr2[n//2 - 1]) / 2.0

    # If the second array is empty, return the median of the first array
    if n == 0:
        return (arr1[0] + arr1[1]) / 2.0 if n == 1 else (arr1[n//2] + arr1[n//2 - 1]) / 2.0

    # Initialize pointers for both arrays
    i = j = 0

    # Binary search until we reach the middle
    while (i + j) <= n:
        # If we've reached the end of arr1, take from arr2
        if i == n:
            return arr2[j + n//2]
        # If we've reached the end of arr2, take from arr1
        elif j == n:
            return arr1[i + n//2]
        # Compare elements and move the pointer in the array with the smaller element
        elif arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    # If the arrays are not of equal length or are empty, return an error
    raise ValueError("Arrays must be of the same size and non-empty")

