def find_kth(arr1, arr2, k):
    # Helper function to partition the arrays
    def partition(arr, low, high, k):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    # Main function logic
    low1, high1 = 0, len(arr1) - 1
    low2, high2 = 0, len(arr2) - 1

    while low1 <= high1 and low2 <= high2:
        mid1 = partition(arr1, low1, high1, (low1 + high1) // 2)
        mid2 = partition(arr2, low2, high2, (low2 + high2) // 2)

        if mid1 + mid2 == k - 1:
            if mid1 == len(arr1) - 1:
                return arr2[mid2]
            elif mid2 == len(arr2) - 1:
                return arr1[mid1]
            elif arr1[mid1] <= arr2[mid2]:
                return arr1[mid1]
            else:
                return arr2[mid2]
        elif mid1 + mid2 > k - 1:
            high1, high2 = mid1 - 1, mid2
        else:
            low1, low2 = mid1 + 1, mid2 + 1

    # If one array is exhausted, return kth element from the other array
    if low1 > high1:
        return arr2[low2 + k - 1]
    else:
