import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    pq = []
    heapq.heappush(pq, (grid[0][0], [grid[0][0]], 0, 0))

    while pq:
        val, path, x, y = heapq.heappop(pq)
        if len(path) == k:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heapq.heappush(pq, (grid[nx][ny], path + [grid[nx][ny]], nx, ny))

