def decimal_to_binary(n):
    if n == 0:
        return "0"
    binary = ""
    while n > 0:
        binary = str(n % 2) + binary
        n = n // 2
    return binary

def babylonian_squareroot(number):
    if number == 0:
        return 0
    estimate = number / 2.0
    while True:
        next_estimate = (estimate + number / estimate) / 2
        if abs(next_estimate - estimate) < 1e-10:  # Precision threshold
            break
        estimate = next_estimate
    return estimate

