def find_Element(arr, ranges, rotations, index):
    # Iterate through each rotation in reverse order
    for i in range(rotations - 1, -1, -1):
        left, right = ranges[i]
        # Check if the index is within the current rotation range
        if left <= index <= right:
            # Adjust the index according to the rotation
            if index == left:
                index = right
            else:
                index -= 1
    # Return the element at the adjusted index
