        return (arr1[0] + arr2[0]) / 2
    if n == 2:
        return ((max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2)

    mid1 = arr1[n // 2]
    mid2 = arr2[n // 2]

    if mid1 < mid2:
        return get_median(arr1[n // 2:], arr2, n - n // 2)
    else:
